function draftSet(){if(st.set)return st.set;const c=PC.config(H()),s=H()?.settings||{};st.set={startYear:c.start?.year||1405,startMonth:c.start?.month||7,hasStart:!!c.start,overtimeFactor:c.overtimeFactor,menuStaff:c.menuStaff,menuManagers:c.menuManagers,tipStep:c.tipStep,advanceWarnPercent:c.advanceWarnPercent,reasons:c.reasons.map(x=>({...x})),items:c.items.map(x=>({...x})),methods:c.methods.slice(),stored:!!(A(s.paymentReasons).length&&A(s.payrollItemTypes).length)};return st.set}
function readSet(root){const d=draftSet(),v=n=>P.en(P.$(`[name=${n}]`,root)?.value||'');Object.assign(d,{startYear:+v('sy'),startMonth:+P.$('[name=sm]',root).value,overtimeFactor:v('of'),menuStaff:v('ms'),menuManagers:v('mm'),tipStep:P.num(P.$('[name=ts]',root).value),advanceWarnPercent:v('aw')});
 d.reasons=P.$$('[data-rs]',root).map(r=>({title:P.$('[data-t]',r).value,kind:P.$('[data-k]',r).value,active:P.$('[data-a]',r).checked}));d.items=P.$$('[data-it]',root).map(r=>({title:P.$('[data-t]',r).value,kind:P.$('[data-k]',r).value,active:P.$('[data-a]',r).checked}));d.methods=P.$$('[data-me]',root).map(i=>i.value);return d}
