const KIND_TONE={advance:'info',salary:'success',tip:'warning',other:'neutral'},KIND_SHORT={advance:'مساعده',salary:'حقوق',tip:'انعام',other:'خارج از حقوق'};
const kindBadge=k=>P.b(KIND_SHORT[k]||k,KIND_TONE[k]||'neutral',1);
const ymKey=(y,m)=>`${y}/${m}`;
function accounts(sel=''){const raw=IC.state.raw||{},acc=A(raw.cashreport?.transferAccounts).filter(a=>a&&(a.status!=='غیرفعال'&&a.isArchived!==true||`account:${a.id}`===sel)).map(a=>[`account:${a.id}`,`کارت / حساب: ${a.name||a.id}`]),loc=A(raw.inventory?.settings?.paymentLocations).filter(l=>l&&(l.isActive!==false||`payment:${l.id}`===sel)).map(l=>[`payment:${l.id}`,`محل پرداخت: ${l.name||l.id}`]);return[...acc,...loc]}
const accountName=k=>{if(!k)return'—';const a=accounts(k).find(x=>x[0]===k);return a?a[1].replace(/^[^:]+: /,''):k};
const payPeople=sel=>staff().filter(p=>p.status==='فعال'||p.id===sel||PC.months(H(),today()).some(x=>PC.inPayroll(H(),p,x.year,x.month))).sort((a,b)=>String(a.name).localeCompare(String(b.name),'fa'));
/* salary month suggested for a person: the oldest finished month with something left, else the last finished month */
function suggestMonth(p){const ms=PC.months(H(),today()).filter(x=>PC.monthState(H(),x.year,x.month,today())!=='current');const left=ms.find(x=>PC.inPayroll(H(),p,x.year,x.month)&&PC.calc(H(),p,x.year,x.month).balance>0.5);const x=left||ms.at(-1)||PC.months(H(),today()).at(-1);return x?ymKey(x.year,x.month):''}
function personCard(p){const ms=PC.personMonths(H(),p.id,today()),tl=PC.tipLedger(H(),p.id),[cy,cm]=today().split('/').map(Number);
 const rows=ms.map(r=>{const cur=r.year===cy&&r.month===cm;return[ML(r.year,r.month)+(cur?' <small class="muted">(جاری)</small>':''),cur?`<small class="muted">پیش‌بینی</small> ${T(PC.forecast(H(),p,r.year,r.month))}`:TS(r.net),T(r.advance),T(r.paid),cur?'—':`<b class="${r.balance>0.5?'':r.balance<-0.5?'down':'up'}">${TS(r.balance)}</b>`]});
 return`${P.table(['ماه حقوق',{t:'خالص',n:1},{t:'مساعده',n:1},{t:'پرداخت',n:1},{t:'مانده',n:1}],rows,{empty:'از شروع حقوق ماهی برای این نفر نیست'})}<div class="minis" style="margin-top:6px"><div class="mini"><small>انعام از شروع</small><b>${T(tl.earned)}</b></div><div class="mini"><small>انعام پرداخت‌شده</small><b>${T(tl.paid)}</b></div><div class="mini"><small>ماندهٔ انعام</small><b>${T(tl.balance)}</b></div></div>`}
