     const [y,mo]=f.mon.split('/').map(Number),cur=y===cy&&mo===cm,tl=PC.tipLedger(H(),p.id),tipAmt=Math.max(0,cfg.tipStep>0?Math.floor(tl.balance/cfg.tipStep)*cfg.tipStep:Math.round(tl.balance));
     xe.innerHTML=(cur?`<label class="row" style="gap:6px"><input type="checkbox" id="pfFinal"> <b>تسویهٔ پایان همکاری</b> — حقوق ماه جاری فقط برای کسی که همکاری‌اش تمام شده پرداخت می‌شود</label>`:'')
